package com.nexusmarket.application.port.out;

import com.nexusmarket.application.query.PageQuery;
import com.nexusmarket.application.query.PageResult;
import com.nexusmarket.domain.returns.Refund;
import java.util.Optional;

/**
 * Output port for refund persistence.
 *
 * <p>Traceability: OBJ-11.</p>
 */
public interface RefundRepository {

    /** Stores the refund, assigning an identifier when it is new. */
    Refund save(Refund refund);

    /** Finds a refund by its identifier. */
    Optional<Refund> findById(Long id);

    /** Finds the refund generated by a return; at most one. */
    Optional<Refund> findByReturnId(Long returnId);

    /** Lists the refunds of an order. */
    PageResult<Refund> findByOrderId(Long orderId, PageQuery query);
}
